class Solution {
    public int reversePairs(int[] nums) {
        return mergeSort(nums, 0, nums.length - 1);
    }
    private int mergeSort(int[] nums, int lo, int hi) {
        if (lo >= hi) return 0;
        int mid = lo + (hi - lo) / 2;
        int count = mergeSort(nums, lo, mid) + mergeSort(nums, mid + 1, hi);
        int j = mid + 1;
        for (int i = lo; i <= mid; i++) {
            while (j <= hi && (long) nums[i] > 2L * nums[j]) j++;
            count += j - (mid + 1);
        }
        int[] temp = new int[hi - lo + 1];
        int i = lo, k = 0;
        j = mid + 1;
        while (i <= mid && j <= hi) {
            if (nums[i] <= nums[j]) temp[k++] = nums[i++];
            else temp[k++] = nums[j++];
        }
        while (i <= mid) temp[k++] = nums[i++];
        while (j <= hi) temp[k++] = nums[j++];
        System.arraycopy(temp, 0, nums, lo, temp.length);
        return count;
    }
}

import java.util.*;

class Solution {
    private int[] tree;
    public int reversePairs(int[] nums) {
        int n = nums.length;
        Set<Long> valSet = new TreeSet<>();
        for (int x : nums) {
            valSet.add((long) x);
            valSet.add(2L * x);
        }
        Map<Long, Integer> rank = new HashMap<>();
        int idx = 1;
        for (long v : valSet) {
            rank.put(v, idx++);
        }
        tree = new int[idx + 1];
        int count = 0;
        for (int i = n - 1; i >= 0; i--) {
            int r = rank.get((long) nums[i]);
            count += query(r - 1);
            int r2 = rank.get(2L * nums[i]);
            update(r2, idx);
        }
        return count;
    }
    private void update(int i, int size) {
        for (; i < size; i += i & (-i)) tree[i]++;
    }
    private int query(int i) {
        int s = 0;
        for (; i > 0; i -= i & (-i)) s += tree[i];
        return s;
    }
}
